import argparse
import hashlib
import os
import requests
from typing import Dict, Optional

def compute_hex_string(body: bytes) -> str:
    return hashlib.sha256(body).hexdigest()[:64].lower()

def load_cache(cache_path: str) -> Dict[str, str]:
    if not os.path.exists(cache_path):
        return {}
    with open(cache_path, 'rb') as f:
        cache = {}
        while True:
            url = f.read(1).decode('utf-8', errors='ignore')
            if not url:
                break
            hex_str = f.read(64).decode('utf-8', errors='ignore')
            cache[url] = hex_str
    return cache

def save_cache(cache_path: str, cache_data: Dict[str, str]) -> None:
    with open(cache_path, 'wb') as f:
        for url, hex_str in cache_data.items():
            f.write(url.encode('utf-8') + b'\x00' + hex_str.encode('utf-8'))

def fetch_url(url: str) -> Optional[bytes]:
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.content
    except (requests.RequestException, ValueError):
        return None

def process_urls(input_path: str, output_path: str, cache_path: str) -> None:
    with open(input_path, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    cache = load_cache(cache_path)
    output_lines = []

    for url in urls:
        if url in cache:
            output_lines.append(f"{url},{cache[url]}")
            continue

        body = fetch_url(url)
        if body is None:
            output_lines.append(f"{url},")
            continue

        hex_str = compute_hex_string(body)
        cache[url] = hex_str
        save_cache(cache_path, cache)

        output_lines.append(f"{url},{hex_str}")

    with open(output_path, 'w') as f:
        f.write('\n'.join(output_lines))

def main():
    parser = argparse.ArgumentParser(description='Process URLs with caching.')
    parser.add_argument('input_file', help='Input file containing URLs')
    parser.add_argument('output_file', help='Output file for results')
    parser.add_argument('cache_file', help='Cache file for URL hashes')
    args = parser.parse_args()

    process_urls(args.input_file, args.output_file, args.cache_file)

if __name__ == "__main__":
    main()

import argparse
import hashlib
import os
import requests
from typing import Dict, List

def compute_hexstring(body: bytes) -> str:
    return hashlib.sha256(body).hexdigest()[:64].lower()

def load_cache(cache_path: str) -> Dict[str, str]:
    if not os.path.exists(cache_path):
        return {}
    with open(cache_path, 'rb') as f:
        cache = {}
        while True:
            url = f.read(64).decode('utf-8').strip()
            if not url:
                break
            hexstring = f.read(64).decode('utf-8').strip()
            cache[url] = hexstring
            if not f.read(1):  # Check for end of file
                break
    return cache

def save_cache(cache_path: str, cache: Dict[str, str]) -> None:
    with open(cache_path, 'wb') as f:
        for url, hexstring in sorted(cache.items()):
            f.write(url.encode('utf-8') + b'\x00' + hexstring.encode('utf-8') + b'\x00')

def process_url(url: str, cache: Dict[str, str]) -> str:
    if url in cache:
        return cache[url]
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        hexstring = compute_hexstring(response.content)
        cache[url] = hexstring
        return hexstring
    except requests.RequestException:
        return ""

def main():
    parser = argparse.ArgumentParser(description='Process URLs and generate HEXSTRING hashes.')
    parser.add_argument('input_file', help='Path to the input file containing URLs')
    parser.add_argument('output_file', help='Path to the output file')
    parser.add_argument('cache_file', help='Path to the cache file')
    args = parser.parse_args()

    cache = load_cache(args.cache_file)

    with open(args.input_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    results = []
    for url in urls:
        hexstring = process_url(url, cache)
        results.append(f"{url},{hexstring}")

    with open(args.output_file, 'w') as f:
        f.write('\n'.join(results))

    save_cache(args.cache_file, cache)

if __name__ == "__main__":
    main()

import json
import hashlib
import requests
import sys
from urllib.parse import urlparse

def get_digest(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        digest = hashlib.sha256(response.text.encode('utf-8')).hexdigest()
        return digest[:64].lower()
    except requests.RequestException:
        return None

def main():
    cache_file = 'cache.json'
    cache = {}

    try:
        with open(cache_file, 'r') as f:
            cache = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        pass

    urls = [line.strip() for line in sys.stdin if line.strip()]

    for url in urls:
        parsed = urlparse(url)
        if not all([parsed.scheme, parsed.netloc]):
            continue  # Skip invalid URLs

        if url in cache:
            print(f"{url},{cache[url]}")
            continue

        digest = get_digest(url)
        if digest is not None:
            cache[url] = digest
            print(f"{url},{digest}")

    with open(cache_file, 'w') as f:
        json.dump(cache, f)

if __name__ == "__main__":
    main()
